import { useEffect, useState } from "react";
import { getNews } from "../services/api";

function News() {
  const [articles, setArticles] = useState([]);
  const [error, setError] = useState("");

  useEffect(() => {
    getNews()
      .then((data) => {
        setArticles(
          (data.articles || []).filter(
            (article) => article.title && article.title !== "[Removed]"
          )
        );
      })
      .catch(() => {
        setError("Новини зараз недоступні. Перевір ключ NewsAPI.");
      });
  }, []);

  return (
    <section className="section" id="news">
      <div className="section-heading">
        <div>
          <span className="eyebrow">БУДЬ У КУРСІ</span>
          <h2>Останні новини</h2>
        </div>
        <span className="section-symbol">↗</span>
      </div>

      {error && <p className="error-message">{error}</p>}

      {!articles.length && !error && (
        <p className="loading-text">Завантажуємо новини...</p>
      )}

      <div className="news-grid">
        {articles.slice(0, 6).map((article, index) => (
          <article className="news-card" key={article.url || index}>
            {article.urlToImage ? (
              <img src={article.urlToImage} alt="" loading="lazy" />
            ) : (
              <div className="news-placeholder">🌦️</div>
            )}

            <div className="news-content">
              <span className="news-date">
                {article.publishedAt
                  ? new Date(article.publishedAt).toLocaleDateString("uk-UA")
                  : "Новини"}
              </span>
              <h3>{article.title}</h3>
              <p>
                {article.description || "Читайте більше за посиланням."}
              </p>
              <a
                href={article.url}
                target="_blank"
                rel="noreferrer"
              >
                Читати далі ↗
              </a>
            </div>
          </article>
        ))}
      </div>
    </section>
  );
}

export default News;
